skip-match.before:
match received {
    Ok(recorded) if recorded.matches(intent) => Ok(recorded),
    Err(ReceiveError::Conflict) => Err(RecordReplyError::Conflict),
    Ok(_) | Err(ReceiveError::Capacity | ReceiveError::Unavailable) => {
        Err(RecordReplyError::Unavailable)
    }
}

skip-match.after:
let _ = intent;
match received {
    Ok(recorded) => Ok(recorded),
    Err(ReceiveError::Conflict) => Err(RecordReplyError::Conflict),
    Err(ReceiveError::Capacity | ReceiveError::Unavailable) => Err(RecordReplyError::Unavailable),
}

clear-terminal.before:
match received {
    Ok(recorded) if recorded.matches(intent) => Ok(recorded),
    Err(ReceiveError::Conflict) => Err(RecordReplyError::Conflict),
    Ok(_) | Err(ReceiveError::Capacity | ReceiveError::Unavailable) => {
        Err(RecordReplyError::Unavailable)
    }
}

clear-terminal.after:
match received {
    Ok(mut recorded) if recorded.matches(intent) => {
        recorded.terminal = false;
        Ok(recorded)
    }
    Err(ReceiveError::Conflict) => Err(RecordReplyError::Conflict),
    Ok(_) | Err(ReceiveError::Capacity | ReceiveError::Unavailable) => {
        Err(RecordReplyError::Unavailable)
    }
}
